package app.loveu;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;
public final class PeriodReminder extends BroadcastReceiver {
 static PendingIntent intent(Context c,String key){return PendingIntent.getBroadcast(c,key.equals("menstrualPartner")?71002:71001,new Intent(c,PeriodReminder.class).setAction("app.loveu.PERIOD_REMINDER").putExtra("key",key),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,String key,long time){AlarmManager alarm=c.getSystemService(AlarmManager.class);if(time>System.currentTimeMillis())alarm.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,intent(c,key));else alarm.cancel(intent(c,key));}
 static void restore(Context c){try{JSONObject s=new Vault(c).read().getJSONObject("settings");for(String key:new String[]{"menstrualSelf","menstrualPartner"})schedule(c,key,s.optLong(key+"Reminder",0));}catch(Exception ignored){}}
 public void onReceive(Context c,Intent i){if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())){restore(c);return;}String key=i.getStringExtra("key");if(!"menstrualSelf".equals(key)&&!"menstrualPartner".equals(key))return;try{synchronized(Vault.class){Vault v=new Vault(c);JSONObject root=v.read(),s=root.getJSONObject("settings");long expected=s.optLong(key+"Reminder",0);if(expected==0||expected>System.currentTimeMillis()+60000)return;s.remove(key+"Reminder");v.write(root);}if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("period-care",Language.ui("关怀提醒"),NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,71000,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(key.equals("menstrualPartner")?71002:71001,new Notification.Builder(c,"period-care").setSmallIcon(app.loveu.R.drawable.ic_loveu).setContentTitle(Language.ui("Love U")).setContentText(Language.ui("你有一条关怀提醒")).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(open).setAutoCancel(true).build());}catch(Exception ignored){}}
}
